const BASE = 'https://api.lokalise.com/api2';
const JOBS = [
  { name: 'Members area', pid: '9933660066825e9a8005c8.58526829',
    langs: [640,765,761,768,818,793,773,799,10159,744,769,774], total: 1138 },
  { name: 'Personality.co', pid: '31393214664f295f94dd86.76792605',
    langs: [640,767,1056,10154,673,757,734,733,10152,10153,749,737,759,748,708,770,754,753,666], total: 7982 }
];
const LIMIT = 200;
const out = [];
for (const j of JOBS) {
  const pages = Math.ceil(j.total / LIMIT);
  for (let p = 1; p <= pages; p++) {
    const qs = [
      'limit=' + LIMIT,
      'page=' + p,
      'include_translations=1',
      'filter_untranslated=1',
      'filter_translation_lang_ids=' + j.langs.join(',')
    ].join('&');
    out.push({ json: { name: j.name, pid: j.pid, page: p, pages: pages, url: BASE + '/projects/' + j.pid + '/keys?' + qs } });
  }
}
return out;

const items = $input.all();
const cfgs = $('Config').all().map(c => c.json);
const acc = {};
const errors = [];
let seen = 0;
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const b = r.body !== undefined ? r.body : r;
  const cfg = cfgs[i];
  if (!Array.isArray(b.keys)) {
    errors.push({ name: cfg.name, page: cfg.page, statusCode: r.statusCode, body: JSON.stringify(b).slice(0, 300) });
    continue;
  }
  if (!acc[cfg.name]) acc[cfg.name] = { name: cfg.name, pid: cfg.pid, keys_seen: 0, archived: 0, no_source: 0, perLang: {}, ns: {}, rows: [] };
  const A = acc[cfg.name];
  for (const k of b.keys) {
    A.keys_seen++; seen++;
    if (k.is_archived) { A.archived++; continue; }
    const kn = (k.key_name && (k.key_name.web || k.key_name.other || k.key_name.ios || k.key_name.android)) || '';
    const sep = kn.indexOf('::') > -1 ? '::' : '.';
    const parts = kn.split(sep);
    const ns = parts.slice(0, Math.min(3, Math.max(1, parts.length - 1))).join(sep) || '(none)';
    A.ns[ns] = (A.ns[ns] || 0) + 1;
    let src = '';
    const miss = [];
    for (const t of (k.translations || [])) {
      if (t.language_iso === 'en') { src = t.translation || ''; continue; }
      if (!t.translation || String(t.translation).trim() === '') {
        A.perLang[t.language_iso] = (A.perLang[t.language_iso] || 0) + 1;
        miss.push(t.language_iso);
      }
    }
    if (!String(src).trim()) { A.no_source++; continue; }
    if (miss.length === 0) continue;
    A.rows.push({ id: k.key_id, k: kn, s: src, m: miss.join(',') });
  }
}
const out = [];
for (const name of Object.keys(acc)) {
  const A = acc[name];
  out.push({ json: {
    name: A.name, pid: A.pid,
    keys_seen: A.keys_seen, archived: A.archived, no_source: A.no_source,
    translatable_rows: A.rows.length,
    missing_segments: Object.values(A.perLang).reduce((a, b2) => a + b2, 0),
    perLang: A.perLang,
    namespaces: Object.entries(A.ns).sort((a, c) => c[1] - a[1]),
    rows: A.rows
  }});
}
out.push({ json: { SUMMARY: true, requests: items.length, keys_seen: seen, errors: errors } });
return out;
